/**
 * HARD RULE Filter:
 * Only return records where:
 * scholarshipType === 'FULL'
 * AND verificationStatus === 'VERIFIED'
 * AND isActive === true
 */
export function getPublicVerifiedScholarshipPrograms(): SaudiScholarshipProgram[] {
  return SAUDI_SCHOLARSHIP_PROGRAMS.filter(
    (program) =>
      program.scholarshipType === 'FULL' &&
      program.verificationStatus === 'VERIFIED' &&
      program.isActive === true
  );
}

